// Applies the native widget, app icons and splash screens to the Android
// project generated by `npx cap add android`.
// Usage: node tools/patch-android.js
const fs = require("fs");
const path = require("path");
const { writePng, drawBlock } = require("./make-icons");

const ROOT = path.join(__dirname, "..");
const CONFIG = JSON.parse(fs.readFileSync(path.join(ROOT, "capacitor.config.json"), "utf8"));
const PACKAGE = CONFIG.appId;
const ANDROID = path.join(ROOT, "android");
const APP = path.join(ANDROID, "app", "src", "main");

if (!fs.existsSync(ANDROID)) {
  console.error('Android project not found. Run "npx cap add android" first.');
  process.exit(1);
}

function findFile(dir, name) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const nested = findFile(full, name);
      if (nested) return nested;
    } else if (entry.name === name) {
      return full;
    }
  }
  return null;
}

function readNative(file) {
  return fs.readFileSync(path.join(ROOT, "native", "android", "java", file), "utf8")
    .replace(/__PACKAGE__/g, PACKAGE);
}

// 1. Java sources
const packageDir = path.join(APP, "java", ...PACKAGE.split("."));
fs.mkdirSync(packageDir, { recursive: true });

for (const file of ["WidgetBridgePlugin.java", "CalendarWidgetProvider.java", "MainActivity.java"]) {
  fs.writeFileSync(path.join(packageDir, file), readNative(file));
}

const mainActivity = findFile(path.join(APP, "java"), "MainActivity.java");
if (mainActivity && mainActivity !== path.join(packageDir, "MainActivity.java")) {
  fs.writeFileSync(mainActivity, readNative("MainActivity.java"));
}

// 2. Layouts, drawables and widget metadata
fs.cpSync(
  path.join(ROOT, "native", "android", "res"),
  path.join(APP, "res"),
  { recursive: true }
);

// 3. Launcher icons (legacy + adaptive foreground) generated from the same pixel art
const DENSITIES = { mdpi: 48, hdpi: 72, xhdpi: 96, xxhdpi: 144, xxxhdpi: 192 };for (const [folder, size] of Object.entries(DENSITIES)) {
  const dir = path.join(APP, "res", `mipmap-${folder}`);
  fs.mkdirSync(dir, { recursive: true });
  writePng(path.join(dir, "ic_launcher.png"), size, size, drawBlock(size, 0.82, 0, "#8bd8ff"));
  writePng(path.join(dir, "ic_launcher_round.png"), size, size, drawBlock(size, 0.82, 0, "#8bd8ff"));
  const foreground = Math.round(size * 2.25);
  writePng(
    path.join(dir, "ic_launcher_foreground.png"),
    foreground,
    foreground,
    drawBlock(foreground, 0.62)
  );
}

const backgroundFile = path.join(APP, "res", "values", "ic_launcher_background.xml");
fs.writeFileSync(
  backgroundFile,
  '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#8BD8FF</color>\n</resources>\n'
);

// 3b. Monochrome status-bar icon for notifications. Android paints it as a mask,
// поэтому важна только форма: белые пиксели на прозрачном фоне.
const STAT_ICON = [
  "................",
  "..##........##..",
  "..##........##..",
  "..############..",
  "..#..........#..",
  "..#..........#..",
  "..#.......#..#..",
  "..#......#...#..",
  "..#.#...#....#..",
  "..#..#.#.....#..",
  "..#...#......#..",
  "..#..........#..",
  "..#..........#..",
  "..############..",
  "................",
  "................"
];

function drawStatusIcon(size) {
  const pixels = Buffer.alloc(size * size * 4);
  const cell = size / 16;
  for (let y = 0; y < 16; y += 1) {
    for (let x = 0; x < 16; x += 1) {
      if (STAT_ICON[y][x] !== "#") continue;
      const left = Math.floor(x * cell);
      const top = Math.floor(y * cell);
      const right = Math.floor((x + 1) * cell);
      const bottom = Math.floor((y + 1) * cell);
      for (let py = top; py < bottom; py += 1) {
        for (let px = left; px < right; px += 1) {
          pixels.set([255, 255, 255, 255], (py * size + px) * 4);
        }
      }
    }
  }
  return pixels;
}

for (const [folder, size] of Object.entries({ mdpi: 24, hdpi: 36, xhdpi: 48, xxhdpi: 72, xxxhdpi: 96 })) {
  const dir = path.join(APP, "res", `drawable-${folder}`);
  fs.mkdirSync(dir, { recursive: true });
  writePng(path.join(dir, "ic_stat_calendar.png"), size, size, drawStatusIcon(size));
}

// 4. Splash screens: sky gradient with the centred grass block
function drawSplash(width, height, night) {
  const pixels = Buffer.alloc(width * height * 4);
  const top = night ? [0x0b, 0x10, 0x20] : [0x8b, 0xd8, 0xff];
  const bottom = night ? [0x26, 0x31, 0x4f] : [0xe9, 0xff, 0xd6];
  for (let y = 0; y < height; y += 1) {
    const mix = height <= 1 ? 0 : y / (height - 1);
    const r = Math.round(top[0] + (bottom[0] - top[0]) * mix);
    const g = Math.round(top[1] + (bottom[1] - top[1]) * mix);
    const b = Math.round(top[2] + (bottom[2] - top[2]) * mix);
    for (let x = 0; x < width; x += 1) {
      const index = (y * width + x) * 4;
      pixels[index] = r;
      pixels[index + 1] = g;
      pixels[index + 2] = b;
      pixels[index + 3] = 255;
    }
  }

  const block = Math.round(Math.min(width, height) * 0.42);
  const art = drawBlock(block, 0.82);
  const startX = Math.floor((width - block) / 2);
  const startY = Math.floor((height - block) / 2);
  for (let y = 0; y < block; y += 1) {
    const target = ((startY + y) * width + startX) * 4;
    art.copy(pixels, target, y * block * 4, (y + 1) * block * 4);
  }
  return pixels;
}

const SPLASHES = [
  ["drawable", 480, 320],
  ["drawable-land-mdpi", 480, 320],
  ["drawable-land-hdpi", 800, 480],
  ["drawable-land-xhdpi", 1280, 720],
  ["drawable-land-xxhdpi", 1600, 960],
  ["drawable-land-xxxhdpi", 1920, 1280],
  ["drawable-port-mdpi", 320, 480],
  ["drawable-port-hdpi", 480, 800],
  ["drawable-port-xhdpi", 720, 1280],
  ["drawable-port-xxhdpi", 960, 1600],
  ["drawable-port-xxxhdpi", 1280, 1920]
];

// Порядок квалификаторов Android фиксирован: ориентация идёт до uiMode, поэтому ночная
// папка — drawable-land-night-hdpi, а не drawable-night-land-hdpi (иначе «Invalid resource
// directory name»). Проверено сборкой в CI.
function nightFolder(folder) {
  const match = folder.match(/^drawable(?:-(land|port))?(?:-(.+))?$/);
  if (!match) throw new Error(`Не разобрал папку splash: ${folder}`);
  const orientation = match[1] ? `-${match[1]}` : "";
  const density = match[2] ? `-${match[2]}` : "";
  return `drawable${orientation}-night${density}`;
}

for (const [folder, width, height] of SPLASHES) {
  const dir = path.join(APP, "res", folder);
  fs.mkdirSync(dir, { recursive: true });
  writePng(path.join(dir, "splash.png"), width, height, drawSplash(width, height, false));
  // Ночной вариант: то же имя ресурса в drawable-*-night, Android сам выберет по uiMode.
  // Светлый splash в тёмной теме — та самая вспышка при запуске.
  const nightDir = path.join(APP, "res", nightFolder(folder));
  fs.mkdirSync(nightDir, { recursive: true });
  writePng(path.join(nightDir, "splash.png"), width, height, drawSplash(width, height, true));
}

// 5. Manifest: widget receiver + boot permission
const manifestFile = path.join(APP, "AndroidManifest.xml");
let manifest = fs.readFileSync(manifestFile, "utf8");

if (!manifest.includes("CalendarWidgetProvider")) {
  const receiver = `
        <receiver
            android:name=".CalendarWidgetProvider"
            android:exported="false"
            android:label="@string/widget_label">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
                <action android:name="android.intent.action.DATE_CHANGED" />
                <action android:name="android.intent.action.TIME_SET" />
                <action android:name="android.intent.action.TIMEZONE_CHANGED" />
                <action android:name="android.intent.action.BOOT_COMPLETED" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/calendar_widget_info" />
        </receiver>
`;
  manifest = manifest.replace("</application>", `${receiver}    </application>`);
}

// Разрешения для напоминаний и виджета. Capacitor сам добавляет часть из них,
// но проверка по имени не даёт дублировать записи при повторном патче.
const PERMISSIONS = [
  "android.permission.RECEIVE_BOOT_COMPLETED",
  "android.permission.POST_NOTIFICATIONS",
  "android.permission.SCHEDULE_EXACT_ALARM"
];
PERMISSIONS.forEach((name) => {
  if (manifest.includes(name)) return;
  manifest = manifest.replace(
    "</manifest>",
    `    <uses-permission android:name="${name}" />\n</manifest>`
  );
});

// Код подключения к синхронизации лежит в localStorage WebView, а системный
// автобэкап уносит его (и дела) в чужое хранилище. Свои данные пользователь
// выгружает экспортом JSON или синхронизацией — автобэкап выключаем.
if (!manifest.includes("android:allowBackup")) {
  manifest = manifest.replace("<application", '<application android:allowBackup="false"');
}
manifest = manifest.replace(/android:allowBackup="true"/, 'android:allowBackup="false"');

fs.writeFileSync(manifestFile, manifest);

// 5b. Debug-манифест: cleartext-HTTP только для LAN-синхронизации.
// В release-сборке HTTP по-прежнему запрещён.
const debugManifest = path.join(ANDROID, "app", "src", "debug", "AndroidManifest.xml");
fs.mkdirSync(path.dirname(debugManifest), { recursive: true });
const debugXml = `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <application android:usesCleartextTraffic="true" />
</manifest>
`;
if (!fs.existsSync(debugManifest) || fs.readFileSync(debugManifest, "utf8") !== debugXml) {
  fs.writeFileSync(debugManifest, debugXml);
  console.log("Debug manifest: cleartext enabled");
}

// 5c. Сеть в release-сборке. HTTP приложению нужен ровно для одного: адрес сервера
// синхронизации вводит пользователь (192.168.x.x, 10.x.x.x или имя хоста), а CSP и
// network-security-config не умеют диапазоны IP — белый список хостов тут не построить.
// Поэтому cleartext разрешён, но только приложение решает, куда ходить.
const networkConfigFile = path.join(APP, "res", "xml", "network_security_config.xml");
fs.mkdirSync(path.dirname(networkConfigFile), { recursive: true });
const networkConfig = `<?xml version="1.0" encoding="utf-8"?>
<!-- HTTP нужен только для сервера синхронизации в локальной сети: адрес вводит
     пользователь, диапазоны IP в network-security-config не поддерживаются. -->
<network-security-config>
    <base-config cleartextTrafficPermitted="true">
        <trust-anchors>
            <certificates src="system" />
        </trust-anchors>
    </base-config>
</network-security-config>
`;
if (!fs.existsSync(networkConfigFile) || fs.readFileSync(networkConfigFile, "utf8") !== networkConfig) {
  fs.writeFileSync(networkConfigFile, networkConfig);
}

if (!/networkSecurityConfig/.test(manifest)) {
  manifest = manifest.replace(
    /android:allowBackup="false"/,
    'android:allowBackup="false"\n        android:networkSecurityConfig="@xml/network_security_config"'
  );
  fs.writeFileSync(manifestFile, manifest);
  console.log("Network security config: cleartext только для приватных диапазонов");
}

// 6. Widget strings
const stringsFile = path.join(APP, "res", "values", "strings.xml");
if (fs.existsSync(stringsFile)) {
  let strings = fs.readFileSync(stringsFile, "utf8");
  if (!strings.includes("widget_label")) {
    strings = strings.replace(
      "</resources>",
      '    <string name="widget_label">Календарь на сегодня</string>\n'
      + '    <string name="widget_description">План на сегодня из Пиксельного календаря</string>\n'
      + "</resources>"
    );
    fs.writeFileSync(stringsFile, strings);
  }
}

// 7. Signing: use a stable release key when CI provides keystore.properties
const gradleFile = path.join(ANDROID, "app", "build.gradle");
let gradle = fs.readFileSync(gradleFile, "utf8");

if (!gradle.includes("keystorePropertiesFile")) {
  gradle = gradle.replace(
    "apply plugin: 'com.android.application'",
    `apply plugin: 'com.android.application'

def keystorePropertiesFile = rootProject.file("keystore.properties")
def keystoreProperties = new Properties()
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}`
  );

  gradle = gradle.replace(
    "    buildTypes {",
    `    signingConfigs {
        release {
            if (keystorePropertiesFile.exists()) {
                storeFile rootProject.file(keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
                storeType 'PKCS12'
            }
        }
    }
    buildTypes {
        debug {
            if (keystorePropertiesFile.exists()) {
                signingConfig signingConfigs.release
            }
        }`
  );

  gradle = gradle.replace(
    "        release {\n            minifyEnabled false",
    `        release {
            if (keystorePropertiesFile.exists()) {
                signingConfig signingConfigs.release
            }
            minifyEnabled false`
  );

  fs.writeFileSync(gradleFile, gradle);
  console.log("Signing config injected into app/build.gradle");
} else {
  console.log("Signing config already present in app/build.gradle");
}

// Version: keep Android versionName/versionCode in sync with package.json.
const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf8"));
const versionName = pkg.version;
const [major, minor, patch] = versionName.split(".").map((part) => Number(part) || 0);
// Разряды не должны пересекаться: при старом major*10000 + minor*100 + patch
// версия 0.100.0 давала тот же код, что 1.0.0 (10000), и обновление не установилось бы.
if (minor > 999 || patch > 999) {
  throw new Error(`Версия ${versionName}: minor и patch должны быть меньше 1000, иначе versionCode пересечёт разряды`);
}
const versionCode = Math.max(1, major * 1000000 + minor * 1000 + patch);
let versioned = fs.readFileSync(gradleFile, "utf8");
versioned = versioned
  .replace(/versionCode \d+/, `versionCode ${versionCode}`)
  .replace(/versionName "[^"]*"/, `versionName "${versionName}"`);
fs.writeFileSync(gradleFile, versioned);
console.log(`Android version: ${versionName} (${versionCode})`);

console.log(`Android project patched for ${PACKAGE}`);
console.log(`MainActivity: ${path.relative(ROOT, mainActivity)}`);
console.log("Widget receiver, icons and splash screens are ready.");
